changeSet.sql:
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_factor_positive CHECK (conversion_factor > 0);
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_precision CHECK (precision BETWEEN 0 AND 18);
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_status CHECK (status IN ('ACTIVE', 'INACTIVE'));
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_version CHECK (version > 0);
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_checksum CHECK (checksum ~ '^[0-9a-f]{64}$');
ALTER TABLE governance_measurement_unit
    ADD CONSTRAINT ck_measurement_unit_base_not_self CHECK (base_unit_ref IS NULL OR base_unit_ref <> id);
ALTER TABLE governance_measurement_unit_revision
    ADD CONSTRAINT ck_measurement_unit_revision_version CHECK (version > 0);
ALTER TABLE governance_measurement_unit_revision
    ADD CONSTRAINT ck_measurement_unit_revision_checksum CHECK (checksum ~ '^[0-9a-f]{64}$');
ALTER TABLE governance_measurement_unit_revision
    ADD CONSTRAINT ck_measurement_unit_revision_snapshot CHECK (jsonb_typeof(snapshot_json) = 'object');
CREATE UNIQUE INDEX uk_measurement_unit_code_ci ON governance_measurement_unit (lower(code));
CREATE INDEX idx_measurement_unit_base_ref ON governance_measurement_unit (base_unit_ref)
    WHERE base_unit_ref IS NOT NULL;

CREATE FUNCTION governance_measurement_unit_revision_immutable() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'MEASUREMENT_UNIT_REVISION_IMMUTABLE';
END;
$$ LANGUAGE plpgsql;

rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM governance_measurement_unit)
       OR EXISTS (SELECT 1 FROM governance_measurement_unit_revision) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MEASUREMENT_UNIT_DATA_EXISTS';
    END IF;
END $$;
